    @Mapping(target = "selfLink", expression = "java(toSelfLink(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
