1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single definition of the region facts: the city-to-region table (Sydney-&gt;NSW,
7	 * Melbourne-&gt;VIC, Brisbane-&gt;QLD) used to validate a postcode against a city's region, and the
8	 * postcode-to-region ranges used to derive an owner's identity region. The request-handling layer
9	 * (which validates a postcode against the city's region and stamps the {@code memberId}'s
10	 * {@code <REGION>} prefix) and the mapping layer (which derives an owner's {@code locality}) both
11	 * depend on this one class, so the memberId region and the locality are always the same value.
12	 *
13	 * <p>Lives beside {@link Owner} — the same home as {@link OwnerIdentity} — so both layers can
14	 * depend on it without a package cycle.
15	 */
16	public final class CityRegions {
17	
18	    /** Region reported for a city that is not in the table. */
19	    public static final String UNKNOWN = "UNKNOWN";
20	
21	    /** City -&gt; canonical region; anything not listed has no known region. */
22	    private static final Map<String, String> CITY_REGION = Map.of(
23	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
24	
25	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
26	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
27	            "NSW", new int[] {2000, 2099},
28	            "VIC", new int[] {3000, 3099},
29	            "QLD", new int[] {4000, 4099});
30	
31	    /** Region -&gt; IANA timezone; anything not listed has no known timezone. */
32	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
33	            "NSW", "Australia/Sydney",
34	            "VIC", "Australia/Melbourne",
35	            "QLD", "Australia/Brisbane");
36	
37	    private CityRegions() {
38	    }
39	
40	    /** The city's canonical region, or {@code null} when the city has no known region. */
41	    public static String regionOf(String city) {
42	        return CITY_REGION.get(city);
43	    }
44	
45	    /**
46	     * The region's inclusive 4-digit postcode range {@code {low, high}}, or {@code null} when the
47	     * region has no known range. The returned array is a fresh copy, so callers cannot mutate the
48	     * shared table.
49	     */
50	    public static int[] postcodeRange(String region) {
51	        int[] range = REGION_POSTCODES.get(region);
52	        return range == null ? null : range.clone();
53	    }
54	
55	    /**
56	     * The region whose postcode range contains {@code postcode}, or {@code null} when the
57	     * postcode is absent, not numeric, or in no known range.
58	     */
59	    public static String regionByPostcode(String postcode) {
60	        if (postcode == null || postcode.isEmpty()) {
61	            return null;
62	        }
63	        int value;
64	        try {
65	            value = Integer.parseInt(postcode);
66	        }
67	        catch (NumberFormatException ex) {
68	            return null;
69	        }
70	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
71	            int[] range = entry.getValue();
72	            if (value >= range[0] && value <= range[1]) {
73	                return entry.getKey();
74	            }
75	        }
76	        return null;
77	    }
78	
79	    /**
80	     * The REGION component of an owner's identity, derived solely from the postcode: the region
81	     * whose range contains {@code postcode}, or {@link #UNKNOWN} when the postcode is absent or in
82	     * no known range. This one value is both the {@code <REGION>} prefix of the owner's
83	     * {@code memberId} and the owner's {@code locality}, so the two are always derived the same
84	     * way and can never diverge.
85	     */
86	    public static String identityRegion(String postcode) {
87	        String region = regionByPostcode(postcode);
88	        return region != null ? region : UNKNOWN;
89	    }
90	
91	    /**
92	     * The version-2 REGION component used <em>inside</em> the owner's identifiers (the
93	     * {@code <REGION>} prefix of the {@code memberId}): the plain {@link #identityRegion(String)}
94	     * region with the fixed {@link IdentityVersion#TAG version tag} mixed in (e.g. {@code V2NSW},
95	     * {@code V2UNKNOWN}). Because a version-1 region code ({@code NSW}, {@code VIC}, {@code QLD},
96	     * {@code UNKNOWN}) can never carry the tag, no value produced under version 1 is produced again.
97	     *
98	     * <p>This is an identifier-only derivation: the user-facing {@code locality} and {@code timezone}
99	     * keep the plain {@link #identityRegion(String)} region, so the tag never leaks into them.
100	     */
101	    public static String identityRegionV2(String postcode) {
102	        return IdentityVersion.TAG + identityRegion(postcode);
103	    }
104	
105	    /**
106	     * The IANA timezone for {@code region} (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
107	     * QLD-&gt;Australia/Brisbane), or {@code null} when the region has no known timezone (including
108	     * {@link #UNKNOWN}).
109	     */
110	    public static String timezoneOf(String region) {
111	        return REGION_TIMEZONE.get(region);
112	    }
113	}
